@app.get("/") def root(): return { "status": "Sistem Unificat Activ", "services": ["Gemini Detection", "Google Places", "Local Bins", "User Management"], "version": "4.1.0" }
@app.get("/health") async def health(): return {"status": "ok"}
@app.post("/analyze", response_model=WasteResult) async def analyze_waste(request: ImageRequest) -> WasteResult: if not request.image: raise HTTPException(status_code=400, detail="Imaginea este goală.")
allowed_types = {"image/jpeg", "image/png", "image/gif", "image/webp"} mime = request.mime_type.lower() if mime not in allowed_types: mime = "image/jpeg"
try: image_bytes = base64.b64decode(request.image, validate=True) except Exception: raise HTTPException(status_code=400, detail="Date base64 invalide.")
client: genai.Client = app.state.client
try: image_part = types.Part.from_bytes(data=image_bytes, mime_type=mime)
response = client.models.generate_content( model="gemini-2.5-flash", contents=[USER_PROMPT, image_part], config=types.GenerateContentConfig( system_instruction=SYSTEM_PROMPT, temperature=0.2, max_output_tokens=1024, response_mime_type="application/json", ), )
raw_text = response.text.strip() if raw_text.startswith("```"): raw_text = raw_text.split("```")[1] if raw_text.startswith("json"): raw_text = raw_text[4:] raw_text = raw_text.strip()
data = json.loads(raw_text)
waste_category = data.get("waste_category", "altele") if waste_category not in CATEGORY_SEARCH_QUERY: waste_category = "altele"
recycling_points: List[RecyclingPoint] = [] local_bins: List[dict] = []
has_location = request.latitude is not None and request.longitude is not None item_identified = data.get("item_name", "Obiect neidentificat") != "Obiect neidentificat"
if has_location and item_identified: recycling_points = await find_recycling_points( http_client=app.state.http_client, api_key=app.state.places_api_key, waste_category=waste_category, latitude=request.latitude, longitude=request.longitude, )
local_bins = get_local_nearest_bins( user_lat=request.latitude, user_lng=request.longitude, bin_type=GEMINI_TO_LOCAL_BIN_MAP.get(waste_category, "general"), max_results=5 )
return WasteResult( item_name=data.get("item_name", "Obiect neidentificat"), waste_category=waste_category, description=data.get("description", ""), disposal_instructions=data.get("disposal_instructions", []), warnings=data.get("warnings", []), is_recyclable=data.get("is_recyclable", False), recycling_points=recycling_points, local_bins=local_bins )
except json.JSONDecodeError as e: raise HTTPException(status_code=500, detail=f"Eroare parsare Gemini: {str(e)}") except Exception as e: error_msg = str(e) if "API_KEY" in error_msg or "authentication" in error_msg.lower(): raise HTTPException(status_code=401, detail="Cheie API Google invalidă.") if "quota" in error_msg.lower() or "429" in error_msg: raise HTTPException(status_code=429, detail="Limita API Google depășită.") raise HTTPException(status_code=500, detail=f"Eroare internă: {error_msg}")
@app.post("/bins/") async def add_bin( lat: float = Form(...), lng: float = Form(...), address: str = Form(""), bin_type: str = Form(...), added_by: str = Form("anonim"), image: Optional[UploadFile] = File(None) ): valid_types = {"plastic", "sticla", "hartie", "general", "electronic"} if bin_type not in valid_types: raise HTTPException(400, f"bin_type invalid. Valori: {valid_types}")
bin_id = str(uuid.uuid4()) image_url = None
if image and image.filename: ext = image.filename.rsplit(".", 1)[-1].lower() filename = f"{bin_id}.{ext}" filepath = os.path.join(UPLOAD_DIR, filename) with open(filepath, "wb") as f: shutil.copyfileobj(image.file, f) image_url = f"/uploads/{filename}"
conn = get_db() conn.execute( "INSERT INTO trash_bins (id, lat, lng, address, bin_type, image_url, added_by) VALUES (?, ?, ?, ?, ?, ?, ?)", (bin_id, lat, lng, address, bin_type, image_url, added_by) ) conn.commit() conn.close()
return {"success": True, "bin_id": bin_id, "message": "Coș adăugat!", "image_url": image_url}
@app.get("/bins/") def list_bins(bin_type: Optional[str] = None): conn = get_db() if bin_type: rows = conn.execute("SELECT * FROM trash_bins WHERE bin_type = ?", (bin_type,)).fetchall() else: rows = conn.execute("SELECT * FROM trash_bins").fetchall() conn.close() return [dict(r) for r in rows]
@app.post("/bins/nearest/") def find_nearest(req: NearestRequest): conn = get_db() bins = conn.execute("SELECT * FROM trash_bins WHERE bin_type = ?", (req.bin_type,)).fetchall() conn.close()
if not bins: raise HTTPException(404, "Nu există coșuri înregistrate de acest tip.")
results = [] for b in bins: dist_m = haversine_km(req.user_lat, req.user_lng, b["lat"], b["lng"]) * 1000 results.append({ **dict(b), "distance_m": round(dist_m), "distance_label": format_distance(dist_m), })
results.sort(key=lambda x: x["distance_m"]) return { "bin_type": req.bin_type, "user_location": {"lat": req.user_lat, "lng": req.user_lng}, "nearest_bins": results[: req.max_results], "total_found": len(bins) }
@app.get("/bins/nearest-simple/") def find_nearest_get(lat: float, lng: float, bin_type: str, max_results: int = 3): return find_nearest(NearestRequest(user_lat=lat, user_lng=lng, bin_type=bin_type, max_results=max_results))
@app.delete("/bins/{bin_id}") def delete_bin(bin_id: str): conn = get_db() result = conn.execute("DELETE FROM trash_bins WHERE id = ?", (bin_id,)) conn.commit() conn.close() if result.rowcount == 0: raise HTTPException(404, "Coșul nu a fost găsit.") return {"success": True, "deleted_id": bin_id}
# --------------------------------------------------------------------------- # Rute API: Utilizatori # ---------------------------------------------------------------------------
@app.post("/users/", response_model=UserResponse, summary="Înregistrează un utilizator nou") def create_user(user: UserCreate): user_id = str(uuid.uuid4()) conn = get_db()
try: conn.execute( "INSERT INTO users (id, username, nume, email, parola, profile_image, nr_puncte) VALUES (?, ?, ?, ?, ?, ?, ?)", (user_id, user.username, user.nume, user.email, user.parola, None, 0) ) conn.commit() except sqlite3.IntegrityError: conn.close() raise HTTPException(status_code=400, detail="Username-ul sau email-ul există deja.")
conn.close()
return { "id": user_id, "username": user.username, "nume": user.nume, "email": user.email, "profile_image": None, "nr_puncte": 0 }
@app.get("/users/all", response_model=List[UserResponse], summary="Obține toți utilizatorii pentru DataGrid") def get_all_users(): conn = get_db() rows = conn.execute("SELECT id, username, nume, email, nr_puncte FROM users").fetchall() conn.close() return [dict(r) for r in rows]
@app.put("/users/{username}/points", summary="Adaugă puncte unui utilizator") def add_points(username: str, data: UserPointsUpdate): conn = get_db()
row = conn.execute("SELECT nr_puncte FROM users WHERE username = ?", (username,)).fetchone() if not row: conn.close() raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.")
nou_total = row["nr_puncte"] + data.puncte_adaugate
conn.execute("UPDATE users SET nr_puncte = ? WHERE username = ?", (nou_total, username)) conn.commit() conn.close()
return {"success": True, "username": username, "puncte_totale": nou_total}
@app.post("/users/login") def login(user: UserLogin): conn = get_db() row = conn.execute( "SELECT * FROM users WHERE (username = ? OR email = ?) AND parola = ?", (user.username_or_email, user.username_or_email, user.parola) ).fetchone() conn.close()
if not row: raise HTTPException(status_code=401, detail="Autentificare eșuată. Verificați username-ul/emailul și parola.")
return { "id": row["id"], "username": row["username"], "nume": row["nume"], "email": row["email"], "nr_puncte": row["nr_puncte"] }
@app.get("/users/{user_id}", response_model=UserResponse, summary="Obține un utilizator după id") def get_user(user_id: str): conn = get_db() row = conn.execute("SELECT id, username, nume, email, profile_image, nr_puncte FROM users WHERE id = ?", (user_id,)).fetchone() conn.close() if not row: raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.") return dict(row)
@app.put("/users/{user_id}", response_model=UserResponse, summary="Actualizează profilul unui utilizator") def update_user(user_id: str, data: UserUpdate): conn = get_db()
fields = [] params: List = [] if data.username is not None: fields.append("username = ?") params.append(data.username) if data.nume is not None: fields.append("nume = ?") params.append(data.nume) if data.email is not None: fields.append("email = ?") params.append(data.email) if data.parola is not None: fields.append("parola = ?") params.append(data.parola)
if fields: params.append(user_id) try: conn.execute(f"UPDATE users SET {', '.join(fields)} WHERE id = ?", tuple(params)) conn.commit() except sqlite3.IntegrityError: conn.close() raise HTTPException(status_code=400, detail="Username-ul sau email-ul există deja.")
row = conn.execute("SELECT id, username, nume, email, profile_image, nr_puncte FROM users WHERE id = ?", (user_id,)).fetchone() conn.close() if not row: raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.") return dict(row)
@app.post("/users/{user_id}/profile-image") def upload_profile_image(user_id: str, image: UploadFile = File(...)): if not image or not image.filename: raise HTTPException(status_code=400, detail="Nu a fost încărcată nicio imagine.")
ext = image.filename.rsplit('.', 1)[-1].lower() filename = f"user_{user_id}.{ext}" filepath = os.path.join(UPLOAD_DIR, filename) with open(filepath, 'wb') as f: shutil.copyfileobj(image.file, f)
image_url = f"/uploads/{filename}"
conn = get_db() conn.execute("UPDATE users SET profile_image = ? WHERE id = ?", (image_url, user_id)) conn.commit() row = conn.execute("SELECT id, username, nume, email, profile_image, nr_puncte FROM users WHERE id = ?", (user_id,)).fetchone() conn.close() if not row: raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.") return dict(row)
