recycling_points: List[RecyclingPoint] = [] local_bins: List[dict] = []
has_location = request.latitude is not None and request.longitude is not None item_identified = data.get("item_name", "Obiect neidentificat") != "Obiect neidentificat"
if has_location and item_identified: recycling_points = await find_recycling_points( http_client=app.state.http_client, api_key=app.state.places_api_key, waste_category=waste_category, latitude=request.latitude, longitude=request.longitude, )
local_bins = get_local_nearest_bins( user_lat=request.latitude, user_lng=request.longitude, bin_type=GEMINI_TO_LOCAL_BIN_MAP.get(waste_category, "general"), max_results=5 )
return WasteResult( item_name=data.get("item_name", "Obiect neidentificat"), waste_category=waste_category, description=data.get("description", ""), disposal_instructions=data.get("disposal_instructions", []), warnings=data.get("warnings", []), is_recyclable=data.get("is_recyclable", False), recycling_points=recycling_points, local_bins=local_bins )
except json.JSONDecodeError as e: raise HTTPException(status_code=500, detail=f"Eroare parsare Gemini: {str(e)}") except Exception as e: error_msg = str(e) if "API_KEY" in error_msg or "authentication" in error_msg.lower(): raise HTTPException(status_code=401, detail="Cheie API Google invalidă.") if "quota" in error_msg.lower() or "429" in error_msg: raise HTTPException(status_code=429, detail="Limita API Google depășită.") raise HTTPException(status_code=500, detail=f"Eroare internă: {error_msg}")
@app.post("/bins/") async def add_bin( lat: float = Form(...), lng: float = Form(...), address: str = Form(""), bin_type: str = Form(...), added_by: str = Form("anonim"), image: Optional[UploadFile] = File(None) ): valid_types = {"plastic", "sticla", "hartie", "general", "electronic"} if bin_type not in valid_types: raise HTTPException(400, f"bin_type invalid. Valori: {valid_types}")
bin_id = str(uuid.uuid4()) image_url = None
if image and image.filename: ext = image.filename.rsplit(".", 1)[-1].lower() filename = f"{bin_id}.{ext}" filepath = os.path.join(UPLOAD_DIR, filename) with open(filepath, "wb") as f: shutil.copyfileobj(image.file, f) image_url = f"/uploads/{filename}"
conn = get_db() conn.execute( "INSERT INTO trash_bins (id, lat, lng, address, bin_type, image_url, added_by) VALUES (?, ?, ?, ?, ?, ?, ?)", (bin_id, lat, lng, address, bin_type, image_url, added_by) ) conn.commit() conn.close()
return {"success": True, "bin_id": bin_id, "message": "Coș adăugat!", "image_url": image_url}
@app.get("/bins/") def list_bins(bin_type: Optional[str] = None): conn = get_db() if bin_type: rows = conn.execute("SELECT * FROM trash_bins WHERE bin_type = ?", (bin_type,)).fetchall() else: rows = conn.execute("SELECT * FROM trash_bins").fetchall() conn.close() return [dict(r) for r in rows]
@app.post("/bins/nearest/") def find_nearest(req: NearestRequest): conn = get_db() bins = conn.execute("SELECT * FROM trash_bins WHERE bin_type = ?", (req.bin_type,)).fetchall() conn.close()
if not bins: raise HTTPException(404, "Nu există coșuri înregistrate de acest tip.")
results = [] for b in bins: dist_m = haversine_km(req.user_lat, req.user_lng, b["lat"], b["lng"]) * 1000 results.append({ **dict(b), "distance_m": round(dist_m), "distance_label": format_distance(dist_m), })
results.sort(key=lambda x: x["distance_m"]) return { "bin_type": req.bin_type, "user_location": {"lat": req.user_lat, "lng": req.user_lng}, "nearest_bins": results[: req.max_results], "total_found": len(bins) }
@app.get("/bins/nearest-simple/") def find_nearest_get(lat: float, lng: float, bin_type: str, max_results: int = 3): return find_nearest(NearestRequest(user_lat=lat, user_lng=lng, bin_type=bin_type, max_results=max_results))
@app.delete("/bins/{bin_id}") def delete_bin(bin_id: str): conn = get_db() result = conn.execute("DELETE FROM trash_bins WHERE id = ?", (bin_id,)) conn.commit() conn.close() if result.rowcount == 0: raise HTTPException(404, "Coșul nu a fost găsit.") return {"success": True, "deleted_id": bin_id}
