@app.post("/users/", response_model=UserResponse, summary="Înregistrează un utilizator nou") def create_user(user: UserCreate): user_id = str(uuid.uuid4()) conn = get_db()
try: conn.execute( "INSERT INTO users (id, username, nume, email, parola, profile_image, nr_puncte) VALUES (?, ?, ?, ?, ?, ?, ?)", (user_id, user.username, user.nume, user.email, user.parola, None, 0) ) conn.commit() except sqlite3.IntegrityError: conn.close() raise HTTPException(status_code=400, detail="Username-ul sau email-ul există deja.")
conn.close()
return { "id": user_id, "username": user.username, "nume": user.nume, "email": user.email, "profile_image": None, "nr_puncte": 0 }
@app.get("/users/all", response_model=List[UserResponse], summary="Obține toți utilizatorii pentru DataGrid") def get_all_users(): conn = get_db() rows = conn.execute("SELECT id, username, nume, email, nr_puncte FROM users").fetchall() conn.close() return [dict(r) for r in rows]
@app.put("/users/{username}/points", summary="Adaugă puncte unui utilizator") def add_points(username: str, data: UserPointsUpdate): conn = get_db()
