fields = [] params: List = [] if data.username is not None: fields.append("username = ?") params.append(data.username) if data.nume is not None: fields.append("nume = ?") params.append(data.nume) if data.email is not None: fields.append("email = ?") params.append(data.email) if data.parola is not None: fields.append("parola = ?") params.append(data.parola)
if fields: params.append(user_id) try: conn.execute(f"UPDATE users SET {', '.join(fields)} WHERE id = ?", tuple(params)) conn.commit() except sqlite3.IntegrityError: conn.close() raise HTTPException(status_code=400, detail="Username-ul sau email-ul există deja.")
row = conn.execute("SELECT id, username, nume, email, profile_image, nr_puncte FROM users WHERE id = ?", (user_id,)).fetchone() conn.close() if not row: raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.") return dict(row)
@app.post("/users/{user_id}/profile-image") def upload_profile_image(user_id: str, image: UploadFile = File(...)): if not image or not image.filename: raise HTTPException(status_code=400, detail="Nu a fost încărcată nicio imagine.")
ext = image.filename.rsplit('.', 1)[-1].lower() filename = f"user_{user_id}.{ext}" filepath = os.path.join(UPLOAD_DIR, filename) with open(filepath, 'wb') as f: shutil.copyfileobj(image.file, f)
image_url = f"/uploads/{filename}"
conn = get_db() conn.execute("UPDATE users SET profile_image = ? WHERE id = ?", (image_url, user_id)) conn.commit() row = conn.execute("SELECT id, username, nume, email, profile_image, nr_puncte FROM users WHERE id = ?", (user_id,)).fetchone() conn.close() if not row: raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.") return dict(row)
