if not row: conn.close() raise HTTPException(status_code=404, detail="Utilizatorul nu a fost găsit.")
# Delete profile image file if it exists if row["profile_image"]: try: filepath = os.path.join(".", row["profile_image"]) if os.path.exists(filepath): os.remove(filepath) except Exception: pass # Ignore file deletion errors
# Delete user from database conn.execute("DELETE FROM users WHERE id = ?", (user_id,)) conn.commit() conn.close()
return {"success": True, "deleted_id": user_id, "message": "Utilizator șters cu succes."}
