// SettingsState type removed from here to avoid duplicate/unused alias (provider defines the canonical type)
type ModalContent = { title: string; body: ReactNode; };
function SettingsCard({ title, description, children, isDark, }: { title: string; description?: string; children: ReactNode; isDark: boolean; }) { return ( <section className={`rounded-xl p-4 shadow ${ isDark ? "border border-white/5 bg-zinc-800 text-white" : "border border-zinc-200 bg-white text-zinc-950" }`} > <div className="mb-4"> <h2 className="text-lg font-semibold">{title}</h2> {description ? ( <p className={`mt-1 text-sm ${isDark ? "text-zinc-400" : "text-zinc-600"}`}> {description} </p> ) : null} </div> {children} </section> ); }
function ToggleRow({ label, description, checked, icon, onChange, isDark, }: { label: string; description: string; // checked can be undefined when the settings object hasn't been populated yet checked?: boolean; icon?: IconDefinition; onChange: (checked: boolean) => void; isDark: boolean; }) { return ( <label className={`flex cursor-pointer items-center justify-between gap-4 rounded-lg px-3 py-3 transition-colors ${ isDark ? "bg-zinc-700/60 text-white hover:bg-zinc-700" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > <span className="flex min-w-0 gap-3"> {icon ? ( <span className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${ isDark ? "bg-zinc-800 text-green-500" : "bg-white text-green-600" }`} > <FontAwesomeIcon icon={icon} className="w-4" /> </span> ) : null} <span> <span className="block font-medium">{label}</span> <span className={`mt-0.5 block text-sm ${ isDark ? "text-zinc-400" : "text-zinc-600" }`} > {description} </span> </span> </span> <input type="checkbox" // ensure the input is always controlled (boolean) to avoid uncontrolled -> controlled warning checked={!!checked} onChange={(event) => onChange(event.target.checked)} className="h-5 w-5 shrink-0 accent-green-600" /> </label> ); }
function ActionButton({ label, icon, danger, onClick, isDark, }: { label: string; icon: IconDefinition; danger?: boolean; onClick: () => void; isDark: boolean; }) { const buttonClassName = danger ? isDark ? "border-red-900/70 text-red-200 hover:bg-red-950/40" : "border-red-300 text-red-700 hover:bg-red-50" : isDark ? "border-zinc-600 text-white hover:bg-zinc-700" : "border-zinc-300 text-zinc-950 hover:bg-zinc-100";
return ( <button className={`flex min-h-12 w-full items-center justify-between rounded-lg border px-3 py-2 text-left transition-colors ${buttonClassName}`} type="button" onClick={onClick} > <span className="flex items-center gap-3 font-medium"> <FontAwesomeIcon icon={icon} className={`w-4 ${danger ? "text-red-400" : "text-green-500"}`} /> {label} </span> <FontAwesomeIcon icon={faChevronRight} className="w-3 text-zinc-500" /> </button> ); }
export default function SettingsPage() { const { settings, updateToggle, updateMaterial, updateSetting, resolvedTheme, isDark, savedMessage, setSavedMessage } = useSettings(); const [modal, setModal] = useState<ModalContent | null>(null);
// resolvedTheme and isDark come from the SettingsProvider
const mainClassName = useMemo(() => { const textSizeClass = settings.textSize === "Small" ? "text-sm" : settings.textSize === "Large" ? "text-lg" : "text-base"; const themeClass = resolvedTheme === "Light" ? "bg-zinc-100 text-zinc-950" : "bg-zinc-900 text-white"; const contrastClass = (settings.toggles as Record<string, boolean>)["High contrast mode"] ? "contrast-125" : "";
return `min-h-screen ${themeClass} ${textSizeClass} ${contrastClass}`; }, [resolvedTheme, settings.textSize, settings.toggles]);
const selectClassName = `w-full rounded-lg border p-3 outline-none ${ isDark ? "border-zinc-600 bg-zinc-700 text-white focus:border-green-500" : "border-zinc-300 bg-white text-zinc-950 focus:border-green-600" }`;
function t(text: string) { return translations[settings.language]?.[text] ?? text; }
// use the update functions provided by the Settings context (destructured above)
function openInfoModal(label: string) { const modalContent: Record<string, ModalContent> = { "Privacy Policy": { title: t("Privacy Policy"), body: ( <p> {t( "Recyvo uses saved preferences, optional location access, and scan permissions to personalize recycling suggestions. You can disable permissions from this page at any time.", )} </p> ), }, "Terms & Conditions": { title: t("Terms & Conditions"), body: ( <p> {t( "Use Recyvo responsibly and check local recycling rules before disposing of items. Community data is informational and may change.", )} </p> ), }, FAQ: { title: t("FAQ"), body: ( <div className="space-y-3"> <p> <strong>{t("How are bins suggested?")}</strong>{" "} {t( "Recyvo uses your selected materials, distance preference, and optional location access.", )} </p> <p> <strong>{t("Are settings saved?")}</strong>{" "} {t("Yes, this page saves them in this browser.")} </p> </div> ), }, "Contact SEB": { title: t("Contact SEB"), body: ( <p> {t( "Send questions to support@recyvo.local or include crash reports so the team can investigate app problems faster.", )} </p> ), }, Changelog: { title: t("Changelog"), body: ( <ul className="list-disc space-y-2 pl-5"> <li>{t("Settings now save locally in your browser.")}</li> <li>{t("Privacy, support, and legal buttons open useful details.")}</li> <li>{t("Download My Data exports your current preferences.")}</li> </ul> ), }, "App version": { title: t("App version"), body: <p>{t("You are using Recyvo version 1.0.0.")}</p>, }, "Last sync": { title: t("Last sync"), body: ( <p> {t( "Your settings and app status were last checked today at 15:20.", )} </p> ), }, Connection: { title: t("Connection"), body: <p>{t("Recyvo is online and ready to sync local changes.")}</p>, }, };
setModal(modalContent[label]); }
function downloadMyData() { const data = { exportedAt: new Date().toISOString(), profile: { level: 7, points: 12450, }, settings, }; const file = new Blob([JSON.stringify(data, null, 2)], { type: "application/json", }); const url = URL.createObjectURL(file); const link = document.createElement("a");
link.href = url; link.download = "recyvo-settings.json"; document.body.appendChild(link); link.click(); link.remove(); URL.revokeObjectURL(url); setSavedMessage("Data export downloaded"); }
function logout() { window.localStorage.removeItem("recyvo-settings"); window.location.href = "../HomePage"; }
return ( // suppressHydrationWarning: many browser extensions inject attributes (eg. fdprocessedid) // which cause harmless hydration diffs. Suppress warnings for this subtree to avoid noisy errors. <main suppressHydrationWarning className={mainClassName}> <div className="mx-auto flex min-h-screen w-full max-w-3xl flex-col"> <header className={`rounded-b-3xl bg-linear-to-r px-6 pt-6 pb-8 text-white ${ isDark ? "from-green-900 to-green-800" : "from-green-700 to-green-600" }`} > <div className="flex items-center justify-between gap-3 mb-5"> <div className="flex items-center gap-2"> <Link href="../HomePage" className="flex h-9 w-9 items-center justify-center rounded-full bg-white/20 hover:bg-white/30 transition-colors" aria-label="Back to home" > <FontAwesomeIcon icon={faArrowLeft} className="w-4" /> </Link> <div className="w-8 h-8 bg-white rounded-full flex items-center justify-center text-green-700"> <FontAwesomeIcon icon={faRobot} className="w-4" /> </div> <div> <p className="text-xs text-green-100">{t("SEB: Eco Assistant")}</p> <h1 className="text-xl font-semibold">{t("Settings")}</h1> </div> </div> <Link href="../HomePage" className="flex items-center gap-2 rounded-lg bg-white/20 px-3 py-2 text-sm font-medium hover:bg-white/30 transition-colors" > <FontAwesomeIcon icon={faHome} className="w-4" /> {t("Home")} </Link> </div>
<div className={`rounded-xl p-4 ${ isDark ? "bg-gray-800 shadow-none" : "bg-white shadow-sm" }`} > <div className="flex justify-between items-start mb-3"> <div> <p className={`text-sm font-medium ${ isDark ? "text-gray-300" : "text-gray-600" }`} > {t("Eco Legend in Training")} </p> <p className={`mt-1 text-2xl font-bold ${ isDark ? "text-white" : "text-black" }`} > {t("Points")}: <span className="text-green-700">12,450</span> </p> </div> <div className="flex flex-col items-center"> <FontAwesomeIcon icon={faTrophy} className="w-6 text-amber-500" /> <span className="text-xs text-gray-500 mt-1">{t("Level 7")}</span> </div> </div>
<div className="flex items-center justify-between text-xs text-gray-500 mb-2"> <span>{t("Progress to Level 8")}</span> <span>70%</span> </div> <div className={`h-2 w-full rounded-full ${ isDark ? "bg-gray-700" : "bg-gray-200" }`} > <div className="bg-green-600 h-2 rounded-full w-[70%]" /> </div> </div> </header>
<div className="flex-1 space-y-4 px-4 py-5"> <SettingsCard title={t("Notifications")} description={t("Choose what Recyvo should remind you about.")} isDark={isDark} > <div className="space-y-2"> {notificationSettings.map((setting) => ( <ToggleRow key={setting.label} {...setting} label={t(setting.label)} description={t(setting.description)} checked={(settings.toggles as Record<string, boolean>)[setting.label]} onChange={(checked) => updateToggle(setting.label, checked)} isDark={isDark} /> ))} </div> </SettingsCard>
<SettingsCard title={t("Privacy")} description={t("Control permissions and how your data is used.")} isDark={isDark} > <div className="space-y-2"> {privacySettings.map((setting) => ( <ToggleRow key={setting.label} {...setting} label={t(setting.label)} description={t(setting.description)} checked={(settings.toggles as Record<string, boolean>)[setting.label]} onChange={(checked) => updateToggle(setting.label, checked)} isDark={isDark} /> ))} </div> <div className="grid gap-2 mt-4 sm:grid-cols-2"> <ActionButton label={t("Download My Data")} icon={faDownload} onClick={downloadMyData} isDark={isDark} /> <ActionButton label={t("Privacy Policy")} icon={faShieldHalved} onClick={() => openInfoModal("Privacy Policy")} isDark={isDark} /> </div> </SettingsCard>
<SettingsCard title={t("Preferences")} description={t("Set the language and app appearance you prefer.")} isDark={isDark} > <div className="space-y-4"> <label className="block"> <span className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faGlobe} className="w-4 text-green-500" /> {t("Language")} </span> <select value={settings.language} onChange={(event) => updateSetting("language", event.target.value)} className={selectClassName} > <option>English (US)</option> <option>Romanian (RO)</option> <option>German (DE)</option> <option>French (FR)</option> <option>Spanish (ES)</option> </select> </label>
<div> <p className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faPalette} className="w-4 text-green-500" /> {t("Theme")} </p>
<div className="grid gap-2 sm:grid-cols-3"> {[ { label: "Light", icon: faSun }, { label: "Dark", icon: faMoon, checked: true }, { label: "Device", icon: faDesktop }, ].map((theme) => ( <label key={theme.label} className={`flex cursor-pointer items-center gap-3 rounded-lg px-3 py-3 transition-colors ${ isDark ? "bg-zinc-700/60 text-white hover:bg-zinc-700" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > <input type="radio" name="theme" checked={settings.theme === theme.label} onChange={() => updateSetting("theme", theme.label)} className="accent-green-600" /> <FontAwesomeIcon icon={theme.icon} className={`w-4 ${ isDark ? "text-zinc-300" : "text-zinc-600" }`} /> <span className="font-medium">{t(theme.label)}</span> </label> ))} </div> </div> </div> </SettingsCard>
<SettingsCard title={t("Recycling Preferences")} description={t("Tune bin suggestions around the way you recycle.")} isDark={isDark} > <div className="mb-4"> <p className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faRecycle} className="w-4 text-green-500" /> {t("Preferred materials")} </p> <div className="grid grid-cols-2 gap-2 sm:grid-cols-4"> {recyclingMaterials.map((material) => ( <label key={material} className={`flex cursor-pointer items-center gap-2 rounded-lg px-3 py-3 transition-colors ${ isDark ? "bg-zinc-700/60 text-white hover:bg-zinc-700" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > <input type="checkbox" // coerce to boolean to ensure the input is always controlled checked={(settings.materials as Record<string, boolean>)[material]} onChange={(event) => updateMaterial(material, event.target.checked) } className="accent-green-600" /> <span className="font-medium">{t(material)}</span> </label> ))} </div> </div>
<div className="grid gap-4 sm:grid-cols-2"> <label className="block"> <span className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faRoute} className="w-4 text-green-500" /> {t("Max nearby distance")} </span> <select value={settings.maxDistance} onChange={(event) => updateSetting("maxDistance", event.target.value) } className={selectClassName} > <option>1 km</option> <option>3 km</option> <option>5 km</option> <option>10 km</option> </select> </label>
<label className="block"> <span className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faLocationDot} className="w-4 text-green-500" /> {t("Distance unit")} </span> <select value={settings.distanceUnit} onChange={(event) => updateSetting("distanceUnit", event.target.value) } className={selectClassName} > <option value="Kilometers">{t("Kilometers")}</option> <option value="Miles">{t("Miles")}</option> </select> </label> </div> </SettingsCard>
<SettingsCard title={t("Accessibility")} description={t("Make Recyvo easier to read and navigate.")} isDark={isDark} > <div className="mb-4"> <p className="mb-2 flex items-center gap-2 font-medium"> <FontAwesomeIcon icon={faTextHeight} className="w-4 text-green-500" /> {t("Text size")} </p> <div className="grid gap-2 sm:grid-cols-3"> {["Small", "Medium", "Large"].map((size) => ( <label key={size} className={`flex cursor-pointer items-center gap-3 rounded-lg px-3 py-3 transition-colors ${ isDark ? "bg-zinc-700/60 text-white hover:bg-zinc-700" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > <input type="radio" name="text-size" checked={settings.textSize === size} onChange={() => updateSetting("textSize", size)} className="accent-green-600" /> <FontAwesomeIcon icon={faUniversalAccess} className={`w-4 ${ isDark ? "text-zinc-300" : "text-zinc-600" }`} /> <span className="font-medium">{t(size)}</span> </label> ))} </div> </div>
<div className="space-y-2"> {accessibilitySettings.map((setting) => ( <ToggleRow key={setting.label} {...setting} label={t(setting.label)} description={t(setting.description)} checked={(settings.toggles as Record<string, boolean>)[setting.label]} onChange={(checked) => updateToggle(setting.label, checked)} isDark={isDark} icon={ setting.label === "High contrast mode" ? faCircleHalfStroke : faArrowsRotate } /> ))} </div> </SettingsCard>
<SettingsCard title={t("Advanced & Security")} isDark={isDark}> <div className="space-y-2"> {securitySettings.map((setting) => ( <ToggleRow key={setting.label} {...setting} label={t(setting.label)} description={t(setting.description)} checked={(settings.toggles as Record<string, boolean>)[setting.label]} onChange={(checked) => updateToggle(setting.label, checked)} isDark={isDark} /> ))} </div> </SettingsCard>
<SettingsCard title={t("App Status")} description={t("Check app health, sync state, and installed version.")} isDark={isDark} > <div className="grid gap-2 sm:grid-cols-2"> {[ { label: "App version", value: "1.0.0", icon: faCodeBranch }, { label: "Last sync", value: "Today, 15:20", icon: faArrowsRotate }, { label: "Connection", value: "Online", icon: faWifi }, { label: "Changelog", value: "View latest updates", icon: faFileContract }, ].map((item) => ( <button key={item.label} type="button" onClick={() => openInfoModal(item.label)} className={`flex items-center gap-3 rounded-lg px-3 py-3 text-left transition-colors ${ isDark ? "bg-zinc-700/60 text-white hover:bg-zinc-700" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-lg ${ isDark ? "bg-zinc-800 text-green-500" : "bg-white text-green-600" }`} > <FontAwesomeIcon icon={item.icon} className="w-4" /> </span> <span> <span className={`block text-sm ${ isDark ? "text-zinc-400" : "text-zinc-600" }`} > {t(item.label)} </span> <span className="block font-medium">{t(item.value)}</span> </span> </button> ))} </div> </SettingsCard>
<SettingsCard title={t("Support & Legal")} description={t("Find help or review Recyvo policies.")} isDark={isDark} > <div className="grid gap-2 sm:grid-cols-2"> {supportActions.map((action) => ( <ActionButton key={action.label} label={t(action.label)} icon={action.icon} onClick={() => openInfoModal(action.label)} isDark={isDark} /> ))} </div> </SettingsCard>
<button type="button" onClick={logout} className="flex w-full items-center justify-center gap-2 bg-red-600 text-white p-3 rounded-xl font-semibold hover:bg-red-700 transition-colors" > <FontAwesomeIcon icon={faSignOutAlt} className="w-4" /> {t("Logout")} </button> <p className={`text-center text-xs ${ isDark ? "text-zinc-500" : "text-zinc-600" }`} > {t(savedMessage)} </p> </div> </div> {modal ? ( <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 px-4" role="dialog" aria-modal="true" aria-labelledby="settings-modal-title" > <div className={`w-full max-w-md rounded-xl border p-5 shadow-xl ${ isDark ? "border-white/10 bg-zinc-800 text-white" : "border-zinc-200 bg-white text-zinc-950" }`} > <div className="mb-3 flex items-start justify-between gap-4"> <h2 id="settings-modal-title" className="text-lg font-semibold"> {modal.title} </h2> <button type="button" onClick={() => setModal(null)} className={`rounded-lg px-3 py-1 text-sm font-medium ${ isDark ? "bg-zinc-700 text-white hover:bg-zinc-600" : "bg-zinc-100 text-zinc-950 hover:bg-zinc-200" }`} > {t("Close")} </button> </div> <div className={`text-sm leading-6 ${ isDark ? "text-zinc-300" : "text-zinc-700" }`} > {modal.body} </div> </div> </div> ) : null} </main> ); }

