const notificationSettings = [ { label: "Nearby bins", description: "Get an alert when useful recycling points are close.", checked: true, }, { label: "Community challenges", description: "Hear about new team goals and weekly eco missions.", checked: true, }, { label: "SEB updates", description: "Receive product tips and assistant improvements.", checked: false, }, ];
